<?php require dirname(__DIR__,2).'/layouts/admin_start.php';$h=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');?>
<section class="equipment-grid"><article class="content-card"><h2>Cadastrar equipamento</h2><form class="admin-form" method="post" action="/admin/equipment/save"><input type="hidden" name="_csrf" value="<?=$h($csrf)?>"><div class="form-grid"><label><span>Código *</span><input name="code" required></label><label><span>Nome *</span><input name="name" required></label><label><span>Fabricante *</span><input name="manufacturer" required></label><label><span>Modelo *</span><input name="model" required></label><label><span>Nº de série</span><input name="serial_number"></label><label><span>Unidade</span><select name="unit_id"><option value="">Todas / não vinculada</option><?php foreach($units as$u):?><option value="<?=$u['id']?>"><?=$h($u['name'])?></option><?php endforeach?></select></label><label><span>Vigente desde *</span><input type="date" name="effective_from" required></label><label class="check"><input type="checkbox" name="active" value="1" checked> Ativo</label></div><button class="button">Salvar equipamento</button></form></article><article class="content-card"><h2>Associar a teste</h2><form class="admin-form" method="post" action="/admin/equipment/assign"><input type="hidden" name="_csrf" value="<?=$h($csrf)?>"><label><span>Teste *</span><select name="test_id" required><option value="">Selecione</option><?php foreach($tests as$t):?><option value="<?=$t['id']?>"><?=$h(($t['code']?:'—').' - '.$t['name'])?></option><?php endforeach?></select></label><label><span>Hemocomponente opcional</span><select name="blood_component_id"><option value="">Todos</option><?php foreach($components as$c):?><option value="<?=$c['id']?>"><?=$h($c['code'].' - '.$c['name'])?></option><?php endforeach?></select></label><label><span>Equipamento *</span><select name="equipment_id" required><option value="">Selecione</option><?php foreach($equipment as$e):if($e['active']):?><option value="<?=$e['id']?>"><?=$h($e['code'].' - '.$e['name'].' '.$e['model'])?></option><?php endif;endforeach?></select></label><label><span>Vigente desde *</span><input type="date" name="effective_from" required></label><label><span>Vigente até</span><input type="date" name="effective_to"></label><label class="check"><input type="checkbox" name="active" value="1" checked> Ativo</label><button class="button">Salvar vínculo</button></form></article></section>
<section class="content-card"><h2>Equipamentos</h2><div class="table-wrap"><table><thead><tr><th>Código</th><th>Nome</th><th>Fabricante / Modelo</th><th>Série</th><th>Unidade</th><th>Vigência</th><th>Status</th></tr></thead><tbody><?php foreach($equipment as$e):?><tr><td><?=$h($e['code'])?></td><td><?=$h($e['name'])?></td><td><?=$h($e['manufacturer'].' / '.$e['model'])?></td><td><?=$h($e['serial_number']?:'—')?></td><td><?=$h($e['unit_name']?:'—')?></td><td><?=date('d/m/Y',strtotime($e['effective_from']))?><?=$e['effective_to']?' a '.date('d/m/Y',strtotime($e['effective_to'])):''?></td><td><?=$e['active']?'Ativo':'Inativo'?></td></tr><?php endforeach?></tbody></table></div></section><section class="content-card"><h2>Vínculos com testes</h2><div class="table-wrap"><table><thead><tr><th>Teste</th><th>Hemocomponente</th><th>Equipamento</th><th>Vigência</th><th>Status</th></tr></thead><tbody><?php foreach($assignments as$a):?><tr><td><?=$h($a['test_code'].' - '.$a['test_name'])?></td><td><?=$h($a['component_code']?:'Todos')?></td><td><?=$h($a['equipment_name'])?></td><td><?=date('d/m/Y',strtotime($a['effective_from']))?><?=$a['effective_to']?' a '.date('d/m/Y',strtotime($a['effective_to'])):''?></td><td><?=$a['active']?'Ativo':'Inativo'?></td></tr><?php endforeach?></tbody></table></div></section><?php require dirname(__DIR__,2).'/layouts/admin_end.php';?>
